// GET /admin/orders
async function listOrders(req, res) {
  const limit = Math.min(Number(req.query.limit ?? 50), 100);
  const cursor = req.query.cursor ? { id: Number(req.query.cursor) } : undefined;

  // 1) 注文はページ単位で取る（件数の上限を設計で決める）
  const orders = await db.order.findMany({
    where: { status: "paid" },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: limit,
    skip: cursor ? 1 : 0,
    cursor,
  });

  if (orders.length === 0) {
    return res.json({ rows: [], nextCursor: null });
  }

  // 2) 関連は「まとめて1回」取り、メモリ上で突き合わせる
  const orderIds = orders.map((o) => o.id);
  const customerIds = [...new Set(orders.map((o) => o.customerId))];

  const [customers, itemCounts] = await Promise.all([
    db.customer.findMany({
      where: { id: { in: customerIds } },
      select: { id: true, name: true },
    }),
    db.orderItem.groupBy({
      by: ["orderId"],
      where: { orderId: { in: orderIds } },
      _count: { _all: true },
    }),
  ]);

  const customerById = new Map(customers.map((c) => [c.id, c]));
  const countByOrderId = new Map(itemCounts.map((c) => [c.orderId, c._count._all]));

  const rows = orders.map((order) => ({
    id: order.id,
    customerName: customerById.get(order.customerId)?.name ?? "(削除済み)",
    itemCount: countByOrderId.get(order.id) ?? 0,
    total: order.total,
  }));

  res.json({ rows, nextCursor: orders.at(-1).id });
}

