class ReceiptMailError extends Error {
  constructor(cause) {
    super("領収書メールの送信に失敗しました");
    this.name = "ReceiptMailError";
    this.cause = cause;
  }
}

async function completePayment(orderId) {
  const order = await db.order.update({
    where: { id: orderId },
    data: { status: "paid", paidAt: new Date() },
  });

  // 決済の成否とメール送信の成否を切り離す。
  // 送信はジョブとして永続化し、失敗しても後から再実行できるようにする。
  try {
    await mailQueue.enqueue({
      type: "receipt",
      orderId: order.id,
      to: order.customerEmail,
      // 同じ注文で二重送信しないための冪等キー
      idempotencyKey: `receipt:${order.id}`,
    });
  } catch (cause) {
    // 「決済は止めない」という要件は守る。ただし黙って捨てない。
    logger.error({
      event: "receipt_mail_enqueue_failed",
      orderId: order.id,
      err: new ReceiptMailError(cause),
    });
    metrics.increment("receipt_mail.enqueue_failed");
    // 送信されていない事実をデータとして残し、再送バッチと管理画面から追える状態にする
    await db.order
      .update({ where: { id: order.id }, data: { receiptMailStatus: "failed" } })
      .catch(() => {});
  }

  return order;
}

