async function reserveSeat(eventId, userId) {
  return db.$transaction(async (tx) => {
    // 条件つきの原子的な更新。判断の根拠（残席 > 0）と減算を1つの文にまとめる。
    // 同時に来た2つのリクエストは、DBが直列化するので必ず片方だけが成功する。
    const updated = await tx.$executeRaw`
      UPDATE events
         SET remaining_seats = remaining_seats - 1
       WHERE id = ${eventId}
         AND remaining_seats > 0
    `;

    if (updated === 0) {
      throw new SoldOutError(eventId);
    }

    // 同一トランザクション内で予約を作る。
    // 予約の作成に失敗すれば残席の減算ごとロールバックされる。
    try {
      return await tx.reservation.create({ data: { eventId, userId } });
    } catch (e) {
      // (event_id, user_id) の UNIQUE 制約違反 = 二重予約
      if (isUniqueViolation(e)) {
        throw new AlreadyReservedError(eventId, userId);
      }
      throw e;
    }
  });
}

