import argon2 from "argon2";

// パスワードハッシュは「遅い・ソルトつき・コストを上げられる」専用アルゴリズムを使う。
// argon2 はソルトを内部で生成し、ハッシュ文字列にパラメータごと埋め込む。
const HASH_OPTIONS = {
  type: argon2.argon2id,
  memoryCost: 19456, // 19 MiB（OWASP の推奨値のひとつ）
  timeCost: 2,
  parallelism: 1,
};

export function hashPassword(password) {
  return argon2.hash(password, HASH_OPTIONS);
}

export async function login(email, password) {
  const user = await db.user.findUnique({ where: { email } });

  if (!user) {
    // ユーザーが存在しない場合もハッシュ検証と同等の時間を消費し、
    // 応答時間からアカウントの存在有無が漏れないようにする
    await argon2.hash(password, HASH_OPTIONS);
    return null;
  }

  // argon2.verify は定数時間比較を行う
  const ok = await argon2.verify(user.passwordHash, password);
  if (!ok) return null;

  // パラメータを引き上げた場合、ログイン成功時に静かに再ハッシュして移行する
  if (argon2.needsRehash(user.passwordHash, HASH_OPTIONS)) {
    await db.user.update({
      where: { id: user.id },
      data: { passwordHash: await hashPassword(password) },
    });
  }

  return user;
}

