// GET /api/invoices/:id
router.get("/api/invoices/:id", requireLogin, async (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    return res.status(400).json({ error: "invalid id" });
  }

  // 所有者条件を「取得したあとの判定」ではなく「問い合わせそのもの」に含める。
  // 条件を書き忘れれば0件になるだけで、他人のデータが返ることはない。
  const invoice = await db.invoice.findFirst({
    where: {
      id,
      OR: [
        { ownerId: req.user.id },
        { organization: { members: { some: { userId: req.user.id, role: { in: ["admin", "billing"] } } } } },
      ],
    },
  });

  // 「存在しない」と「権限が無い」を区別せず、どちらも404を返す。
  // 権限の無いIDを試しても、請求書の存在有無が分からない。
  if (!invoice) {
    logger.warn({ event: "invoice_access_denied", userId: req.user.id, invoiceId: id });
    return res.status(404).json({ error: "not found" });
  }

  res.set("Cache-Control", "private, no-store");
  res.json(invoice);
});

