// --- サーバー側: トークンは HttpOnly Cookie で発行する ---
app.post("/api/login", async (req, res) => {
  const user = await authenticate(req.body.email, req.body.password);
  if (!user) return res.status(401).json({ error: "invalid credentials" });

  const accessToken = signAccessToken(user, { expiresIn: "15m" });
  const refreshToken = await issueRefreshToken(user); // DBに保存し、失効させられるようにする

  const secure = process.env.NODE_ENV === "production";

  res.cookie("access_token", accessToken, {
    httpOnly: true,   // JavaScript から読めない
    secure,           // HTTPS 以外では送らない
    sameSite: "lax",  // 他サイトからの遷移では送られない
    path: "/",
    maxAge: 15 * 60 * 1000,
  });
  res.cookie("refresh_token", refreshToken, {
    httpOnly: true,
    secure,
    sameSite: "strict",
    path: "/api/auth/refresh", // リフレッシュ用の経路にだけ送る
    maxAge: 14 * 24 * 60 * 60 * 1000,
  });

  res.json({ user: { id: user.id, name: user.name } });
});

// --- クライアント側: トークンに一切触れない ---
async function login(email, password) {
  const res = await fetch("/api/login", {
    method: "POST",
    credentials: "same-origin", // Cookie はブラウザが自動で運ぶ
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error("LOGIN_FAILED");
  return res.json();
}

// SameSite だけに頼らず、状態を変える操作には CSRF トークンを併用する
async function post(url, body) {
  return fetch(url, {
    method: "POST",
    credentials: "same-origin",
    headers: {
      "Content-Type": "application/json",
      "X-CSRF-Token": getCsrfTokenFromMeta(),
    },
    body: JSON.stringify(body),
  });
}

