// 既定値は「最も安全な状態」に置く。
// 危険な設定は、権限を持つ人が意図的に有効化したときにだけ有効になる（opt-in）。
const SAFE_WORKSPACE_DEFAULTS = {
  visibility: "private",       // 明示的に公開操作をするまで非公開
  allowExternalShare: false,   // 社外共有は管理者が明示的に解禁する
  defaultMemberRole: "viewer", // 最小権限。昇格は個別に行う
  retentionDays: 365,          // 無期限保持をやめ、期限を既定で持つ
  auditLogEnabled: true,       // 事後に追跡できないと、事故の範囲が確定できない
};

async function createWorkspace({ name, ownerId, overrides = {}, actor }) {
  // 既定から外れる設定は、誰がいつ有効にしたのかを記録する
  const requestedUnsafe = Object.entries(overrides).filter(
    ([key, value]) => SAFE_WORKSPACE_DEFAULTS[key] !== value
  );

  if (requestedUnsafe.length > 0) {
    assertCanConfigureWorkspace(actor); // 危険な設定の変更には権限を要求する
  }

  const workspace = await db.workspace.create({
    data: { name, ownerId, ...SAFE_WORKSPACE_DEFAULTS, ...overrides },
  });

  for (const [key, value] of requestedUnsafe) {
    await auditLog.record({
      event: "workspace_unsafe_default_overridden",
      workspaceId: workspace.id,
      actorId: actor.id,
      setting: key,
      value,
    });
  }

  return workspace;
}

