// ORDER BY にはプレースホルダが使えないため、許可リストで列名を解決する。
const SORTABLE_COLUMNS = {
  name: "name",
  email: "email",
  created_at: "created_at",
};

function escapeLike(input) {
  // LIKE のワイルドカード自体を検索語として扱えるようにする
  return input.replace(/[\\%_]/g, (c) => "\\" + c);
}

async function searchUsers({ keyword, status, sort = "created_at", direction = "desc" }) {
  const column = SORTABLE_COLUMNS[sort];
  if (!column) {
    throw new BadRequestError(`unsupported sort key: ${sort}`);
  }
  const order = direction === "asc" ? "ASC" : "DESC";

  // 値はすべてプレースホルダで渡す。文字列連結でSQLを組み立てない。
  return db.$queryRaw`
    SELECT id, name, email, status
    FROM users
    WHERE name LIKE ${"%" + escapeLike(keyword) + "%"} ESCAPE '\\'
      AND status = ${status}::user_status
    ORDER BY ${db.raw(column)} ${db.raw(order)}
    LIMIT 100
  `;
}

