import { randomUUID } from "node:crypto";

// エラーの詳細はサーバーのログへ。クライアントには追跡IDだけを返す。
app.use((err, req, res, next) => {
  if (res.headersSent) {
    return next(err); // 送信済みなら Express の既定ハンドラに委ねる
  }

  const traceId = req.traceId ?? randomUUID();
  const status = err.statusCode ?? 500;

  // 構造化ログ。調査に必要な文脈は全てこちら側に残す。
  logger.error({
    event: "unhandled_error",
    traceId,
    status,
    method: req.method,
    path: req.path,
    userId: req.user?.id,
    err: { name: err.name, message: err.message, stack: err.stack },
  });

  // 想定内のエラー（4xx）だけはメッセージを返してよい。
  // 500 は内部の情報を含みうるので、固定文言に置き換える。
  const body =
    status < 500
      ? { error: err.publicMessage ?? err.message, traceId }
      : { error: "サーバー内部でエラーが発生しました", traceId };

  res.status(status).json(body);
});

