-- 破壊的な変更は expand / migrate / contract の3段階に分ける。
-- 各段階は単独でデプロイでき、1つ前のバージョンのコードでも動く。

-- === 段階1: expand（デプロイ #1 の前に実行）===
-- 新しい列を追加するだけ。旧コードは full_name を読み書きし続けられる。
ALTER TABLE users ADD COLUMN display_name TEXT;

-- 既存データをコピー（大きなテーブルではバッチで分割する）
UPDATE users SET display_name = full_name WHERE display_name IS NULL;

-- 移行期間中、どちらの列に書かれても両方が同じ値になるようにする
CREATE FUNCTION sync_user_name() RETURNS trigger AS $$
BEGIN
  IF NEW.display_name IS DISTINCT FROM OLD.display_name THEN
    NEW.full_name := NEW.display_name;
  ELSIF NEW.full_name IS DISTINCT FROM OLD.full_name THEN
    NEW.display_name := NEW.full_name;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER users_sync_name
  BEFORE INSERT OR UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION sync_user_name();

-- === 段階2: migrate（デプロイ #1）===
-- アプリを display_name の読み書きに切り替える。
-- 旧インスタンスが full_name を使っていてもトリガが同期するので壊れない。
-- 全インスタンスの入れ替え完了を確認し、full_name への参照が消えたことを
